const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Configuration
const validEntityTypes = ['recipes', 'translations', 'trainings', 'articles', 'posts'];
const validActions = ['comments', 'rating', 'favorite', 'favorites'];
const validMethods = ['GET', 'POST', 'DELETE'];
const validProjects = ['bot-appetit', 'torah-bot', 'torah-fun'];

// Entity type to API path mapping
const entityApiMapping = {
  'recipes': '/api/entities/recipes',
  'translations': '/api/entities/translations',
  'trainings': '/api/entities/trainings',
  'articles': '/api/entities/articles',
  'posts': '/api/entities/posts'
};

const errors = [];

// Validate entity_type
const entity_type = body.entity_type;
if (!entity_type || !validEntityTypes.includes(entity_type)) {
  errors.push(`Invalid entity_type: '${entity_type}'. Valid: ${validEntityTypes.join(', ')}`);
}

// Validate action
const action = body.action;
if (!action || !validActions.includes(action)) {
  errors.push(`Invalid action: '${action}'. Valid: ${validActions.join(', ')}`);
}

// Validate method (default POST)
const method = (body.method || 'POST').toUpperCase();
if (!validMethods.includes(method)) {
  errors.push(`Invalid method: '${method}'. Valid: ${validMethods.join(', ')}`);
}

// Validate entity_id (UUID format)
const entity_id = body.entity_id;
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!entity_id) {
  errors.push('Missing entity_id');
} else if (!uuidRegex.test(entity_id)) {
  errors.push('Invalid entity_id: must be UUID format');
}

// Validate project_id from header
const project_id = headers['x-project-id'];
if (!project_id || !validProjects.includes(project_id)) {
  errors.push(`Missing or invalid X-Project-ID header. Valid: ${validProjects.join(', ')}`);
}

// Validate discord_user_id for non-GET requests
if (method !== 'GET' && !body.discord_user_id) {
  errors.push('Missing discord_user_id in body');
}

// Action-specific validations
if (action === 'comments' && method === 'POST') {
  if (!body.content || body.content.trim().length === 0) {
    errors.push('Missing or empty content for comment');
  } else if (body.content.length > 500) {
    errors.push('Comment content exceeds 500 characters');
  }
}

if (action === 'rating' && method === 'POST') {
  const score = parseInt(body.score);
  if (isNaN(score) || score < 1 || score > 5) {
    errors.push('Invalid score: must be integer 1-5');
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Build API path for entity lookup
const apiBasePath = entityApiMapping[entity_type];

return [{
  json: {
    valid: true,
    entity_type,
    entity_id,
    action,
    method,
    project_id,
    api_base_path: apiBasePath,
    discord_user_id: body.discord_user_id || null,
    discord_username: body.discord_username || null,
    content: body.content ? body.content.trim() : null,
    score: body.score ? parseInt(body.score) : null,
    comment_id: body.comment_id || null
  }
}];

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

if (statusCode >= 400 || !body || body.detail) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `${inputData.entity_type} with id '${inputData.entity_id}' not found`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Extract entity info for notifications
let entityTitle = body.title || body.name || 'Untitled';
let creatorDiscordUserId = body.discord_user_id || body.creator_discord_user_id || null;

return [{
  json: {
    found: true,
    ...inputData,
    entity_title: entityTitle,
    creator_discord_user_id: creatorDiscordUserId
  }
}];

const data = $input.first().json;

// Comments action handler
if (data.method === 'GET') {
  return [{
    json: {
      ...data,
      api_method: 'GET',
      api_url: `${data.api_base_path}/${data.entity_id}/comments`,
      api_body: null
    }
  }];
}

if (data.method === 'POST') {
  return [{
    json: {
      ...data,
      api_method: 'POST',
      api_url: `${data.api_base_path}/${data.entity_id}/comments`,
      api_body: {
        discord_user_id: data.discord_user_id,
        discord_username: data.discord_username,
        content: data.content
      }
    }
  }];
}

if (data.method === 'DELETE') {
  return [{
    json: {
      ...data,
      api_method: 'DELETE',
      api_url: `${data.api_base_path}/${data.entity_id}/comments/${data.comment_id}`,
      api_body: {
        discord_user_id: data.discord_user_id
      }
    }
  }];
}

return [{ json: data }];

