return [{ json: data }];

const data = $input.first().json;

// Get user's favorites list
// Note: For this action, entity_id in the body is actually user_id
return [{
  json: {
    ...data,
    api_method: 'GET',
    api_url: `${data.api_base_path}/favorites/${data.discord_user_id}`,
    api_body: null
  }
}];

const apiResponse = $input.first().json;

// Get action data - try multiple sources
let actionData;
try {
  actionData = $('Switch Action').first().json;
} catch (e) {
  // Fallback to Check Entity if Switch Action not found
  actionData = $('Check Entity').first().json;
}

const statusCode = apiResponse.statusCode || 200;
const body = apiResponse.body || apiResponse;

// Handle API errors
if (statusCode >= 400 || body.detail) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: body.detail || 'API request failed',
        status: 'API_ERROR'
      },
      meta: {
        entity_type: actionData.entity_type,
        entity_id: actionData.entity_id,
        action: actionData.action,
        project_id: actionData.project_id
      }
    }
  }];
}

// Build success response based on action
let response = {
  success: true,
  data: null,
  meta: {
    entity_type: actionData.entity_type,
    entity_id: actionData.entity_id,
    action: actionData.action,
    project_id: actionData.project_id,
    method: actionData.method
  }
};

switch (actionData.action) {
  case 'comments':
    if (actionData.method === 'GET') {
      response.data = { comments: Array.isArray(body) ? body : [body] };
    } else if (actionData.method === 'POST') {
      response.data = {
        comment: {
          id: body.id,
          content: body.content,
          discord_user_id: body.discord_user_id,
          created_at: body.created_at
        }
      };
      // Notify creator if different from commenter
      if (actionData.creator_discord_user_id &&
          actionData.creator_discord_user_id !== actionData.discord_user_id) {
        response.notify = {
          type: 'new_comment',
          to_discord_user_id: actionData.creator_discord_user_id,
          entity_type: actionData.entity_type,
          entity_id: actionData.entity_id,
          entity_title: actionData.entity_title,
          from_username: actionData.discord_username || actionData.discord_user_id,
          preview: actionData.content ? actionData.content.substring(0, 100) : ''
        };
      }
    } else if (actionData.method === 'DELETE') {
      response.data = { deleted: true };
    }
    break;

  case 'rating':
    if (actionData.method === 'GET') {
      response.data = {
        average: parseFloat(body.average) || 0,
        count: parseInt(body.count) || 0,
        ratings: body.ratings || []
      };
    } else {
      response.data = {
        rating: {
          id: body.id,
          score: body.rating || body.score,
          discord_user_id: body.discord_user_id
        }
      };
      // Notify creator
      if (actionData.creator_discord_user_id &&
          actionData.creator_discord_user_id !== actionData.discord_user_id) {
        response.notify = {
          type: 'new_rating',
          to_discord_user_id: actionData.creator_discord_user_id,
          entity_type: actionData.entity_type,
          entity_id: actionData.entity_id,
          entity_title: actionData.entity_title,
          from_username: actionData.discord_username || actionData.discord_user_id,
          score: actionData.score,
          stars: '⭐'.repeat(actionData.score || 0)
        };
      }
    }
    break;

  case 'favorite':
    if (actionData.method === 'GET') {
      response.data = { is_favorite: body.is_favorite || false };
    } else {
      response.data = {
        is_favorite: body.is_favorite !== undefined ? body.is_favorite : true,
        action_taken: body.action || (actionData.method === 'DELETE' ? 'removed' : 'added')
      };
    }
    break;

  case 'favorites':
    response.data = { favorites: Array.isArray(body) ? body : [] };
    break;

  default:
    response.data = body;
}

return [{ json: response }];

